RAW=RAW[0].strip().splitlines()
assert len(RAW)==105, len(RAW)
lessons=[]
for row in RAW:
    cells=[x.strip() for x in row.rstrip('|').split('|')]
    assert len(cells)==10,(len(cells),row[:60])
    num=int(cells[0]); title,concept,ui,ex,outcome,trap,repair,challenge,mastery=cells[1:]
    # map lesson number to stages
    breaks=[7,14,20,30,37,46,54,61,68,75,82,90,96,105]
    stage=next(i+1 for i,end in enumerate(breaks) if num<=end)
    prereq=[] if num==1 else [f'L{num-1:03}']
    if stage==14: prereq=[f'L{breaks[stage-2]:03}']; # stages prerequisite plus applied project references added below
    lesson={ 'id':f'L{num:03}', 'stage':stage,'title':title,'level':STAGES[stage-1][1],
        'objective':f'Explain and demonstrate {title.lower()} without relying on a memorized click sequence.',
        'prerequisites':prereq,
        'concept':concept,
        'why':f'{STAGES[stage-1][3]} In this lesson, the decision becomes concrete: {concept}',
        'ui':ui,
        'steps': [s.strip() for s in re.split(r';\s*',ex) if s.strip()],
        'exercise':ex,'expected':outcome,'use_cases':f'Use this technique when producing a project that needs {STAGES[stage-1][2].lower()}. It matters most when choices must survive revisions.',
        'mistakes':[trap], 'fixes':[repair], 'tip':f'Keep a duplicate practice sequence, compare before/after and verify the whole change rather than just a frozen preview frame.',
        'challenge':challenge,'mastery':mastery,
        'related':[], 'ref_tags':[],
        'duration':18 if stage<=3 else (24 if stage<=10 else 28)
    }
    if len(lesson['steps'])<2: lesson['steps'] += ['Observe the Program Monitor, timeline positions, and any modified controls before you undo or save.','Repeat once, explaining which source frames or output signals changed.']
    else: lesson['steps'] += ['Compare before and after at normal playback; save a named practice version and record one observation.']
    if stage==14: lesson['duration']=50 if num<105 else 300
    lessons.append(lesson)
assert all(x['stage']==next(i+1 for i,b in enumerate([7,14,20,30,37,46,54,61,68,75,82,90,96,105]) if int(x['id'][1:])<=b) for x in lessons)
for n,L in enumerate(lessons):
    if n>0: L['related'].append(lessons[n-1]['id'])
    if n<len(lessons)-1: L['related'].append(lessons[n+1]['id'])
