for i,(name,level,goal,idea) in enumerate(STAGES,1):
 ids=[l['id'] for l in lessons if l['stage']==i]
 stages.append({'id':i,'title':name,'level':level,'goal':goal,'thesis':idea,'lessons':ids,'quiz':[q['id'] for q in quizzes if q['stage']==i], 'challenge':lessons[[l['id'] for l in lessons].index(ids[-1])]['challenge'],'pass':f'Complete the stage exercise, score at least 2/3 in the stage knowledge check, and meet the final lesson mastery criterion.'})
