# output data
content={'meta':{'title':'Premiere, Explained','subtitle':'An offline Windows-first course and reference','version':VERSION,'verified_on':DATE,'research_cutoff':'2026-10-28 (Oct 29 requested date not yet reached)','edition':'3.0 (cross-manual comparative audit)','notes':'Adobe Premiere desktop (formerly commonly called Premiere Pro), Windows 11; course website opens from file:// on Linux/Windows'},'stages':stages,'lessons':lessons,'quizzes':quizzes,'shortcuts':shortcuts,'effects':fx,'transitions':trans,'panels':panels,'glossary':glossary,'troubleshooting':troubles,'recipes':recipes,'sources':[{'id':k,'title':v[0],'url':v[1],'version':v[2],'verified':DATE,'notes':v[3]} for k,v in SOURCE.items()],'version_audit':[{'topic':a,'version':b,'stable':c,'notes':d} for a,b,c,d in version_audit]}
(P/'data'/'course.json').write_text(json.dumps(content,indent=2,ensure_ascii=False),encoding='utf8')
(P/'data.js').write_text('window.PREMIERE_MANUAL = '+json.dumps(content,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf8')
for key,fn,cols in [('shortcuts','SHORTCUTS.csv',['category','command','windows','context','status','source']),('effects','EFFECTS.csv',['name','kind','category','purpose','parameters','example','performance','limitations','status','related','source']),('transitions','TRANSITIONS.csv',['name','category','description','parameters','example','limitations','status','source']),('panels','PANELS_AND_TOOLS.csv',['name','purpose','controls','shortcut','relationship','source']),('glossary','GLOSSARY.csv',['term','definition','example','lesson']),('troubleshooting','TROUBLESHOOTING.csv',['title','causes','tests','confirm','prevention','side_effects','lesson'])]:
 with (P/fn).open('w',encoding='utf8',newline='') as f:
  w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows([{x:row.get(x,'') for x in cols} for row in content[key]])
# Markdown comprehensive edition from same source
lines=[f'# {content["meta"]["title"]} — Complete Learning Manual', '', 'Windows edition • Release 26.5.2 • Verified October 28, 2026', '', 'This Markdown edition is generated from exactly the same data as the offline website. The offline reading website includes interactive tests and progress tracking, which Markdown cannot provide.', '', '## Reading path', '']
for s in stages: lines.append(f'- **Stage {s["id"]} – {s["title"]}** ({s["level"]}): {s["goal"]}; {len(s["lessons"])} lessons.')
for s in stages:
 lines += ['',f'## Stage {s["id"]}: {s["title"]}', '',s['thesis'], '',f'**Stage challenge:** {s["challenge"]}', '']
 for L in [l for l in lessons if l['stage']==s['id']]:
  lines += [f'### {L["id"]} · {L["title"]}', '',f'**Learning outcome:** {L["objective"]}',f'**Prerequisite:** {", ".join(L["prerequisites"]) or "None"}',f'**Level / typical time:** {L["level"]} · {L["duration"]} min','', '**Concept / mental model**',L['concept'],'','**Why the operation works**',L['why'],'','**Second-pass technical explanation**',L['deep_dive'],'','**Where to work on Windows**',L['ui'],'','**Reproducible exercise**']
  lines += [f'{i}. {step}' for i,step in enumerate(L['steps'],1)]
  lines += ['','**Expected result**',L['expected'],'','**When to use**',L['use_cases'],'','**Common mistake**',L['mistakes'][0],'','**Correction**',L['fixes'][0],'','**Professional habit**',L['tip'],'','**Adversarial self-test**',L['review_test'],'','**Challenge**',L['challenge'],'','**Mastery proof**',L['mastery'],'','**Related lessons:** '+', '.join(L['related']),'**Adobe source keys:** '+', '.join(L['ref_tags']),'']
 lines += ['### Stage knowledge check','','Answer before viewing the correct choice.','']
 for q in [q for q in quizzes if q['stage']==s['id']]:
  lines += [f'**{q["question"]}**','']+ [f'- {chr(65+i)}. {choice}' for i,choice in enumerate(q['options'])] + ['','*Answer: '+chr(65+q['answer'])+' — '+q['explanation']+'*','']
lines += ['## Workflow recipes','']
for r in recipes:
 lines += [f'### {r["title"]}',f'Prerequisites: {", ".join(r["prerequisites"])}','']+[f'{i}. {s}' for i,s in enumerate(r['steps'],1)]+['',r['check'],'']
lines+=['## Troubleshooting','']
for t in troubles: lines += [f'### {t["title"]}',f'**Likely causes:** {t["causes"]}',f'**Test/fix:** {t["tests"]}',f'**Verify:** {t["confirm"]}',f'**Prevention:** {t["prevention"]}',f'**Possible trade-off:** {t["side_effects"]}','']
for key,heading in [('shortcuts','Keyboard shortcuts'),('effects','Effects reference'),('transitions','Transitions reference'),('panels','Panels and tools'),('glossary','Glossary')]:
 lines += [f'## {heading}','']
 for row in content[key]:
  if key=='shortcuts': line=f'- **{row["command"]}** — `{row["windows"]}` ({row["context"]}; {row["status"]}).'
  elif key=='effects': line=f'- **{row["name"]}** ({row["kind"]}; {row["category"]}): {row["purpose"]}. Controls: {row["parameters"]}. Example: {row["example"]} Limitation: {row["limitations"]} *{row["status"]}.*'
  elif key=='transitions': line=f'- **{row["name"]}** ({row["category"]}): {row["description"]} {row["limitations"]} *{row["status"]}.*'
  elif key=='panels':line=f'- **{row["name"]}**: {row["purpose"]}. Controls: {row["controls"]}. Shortcut: {row["shortcut"]}.'
  else:line=f'- **{row["term"]}**: {row["definition"]} Example: {row["example"]} See {row["lesson"]}.'
  lines.append(line)
 lines.append('')
lines += ['## Version feature audit','']
for r in content['version_audit']: lines.append(f'- **{r["topic"]}** — {r["version"]}; stable: {r["stable"]}. {r["notes"]}')
lines+=['','## Official research sources','']
for r in content['sources']:lines.append(f'- **[{r["id"]}] {r["title"]}**: {r["url"]} ({r["version"]}; verified {r["verified"]}). {r["notes"]}')
(P/'ALL_CONTENT.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
